export type RichTextInputMinRows = NonNullable<RichTextInputProps['minRows']>

export type RichTextInputMaxRows = NonNullable<RichTextInputProps['maxRows']>

export type RichTextToolbarPlacement = NonNullable<RichTextInputProps['toolbarPlacement']>

export interface RichTextEntityOption {
  id: string
  label: string
  description?: string
  icon?: IconRole
  leading?: NodeTemplate
  entityLabel?: string
}

export interface RichTextEntitySource {
  kind: string
  trigger: string
  label: string
  options: RichTextEntityOption[]
  filter?: 'contains' | 'startsWith' | false
  loading?: boolean
  error?: string
  onQueryChange?: (query: string) => void
}

export interface RichTextInputSelection {
  empty: boolean
  text: string
  range: RichTextRange
}

export interface RichTextInputEditor {
  focus(): void
  clear(): void
  insertText(text: string): void
  insertEntity(entity: { kind: string; id: string; label: string }): void
  annotate(id: string): boolean
  removeAnnotation(id: string): boolean
  readonly value: RichTextDocument
  readonly empty: boolean
  readonly length: number
  readonly overLimit: boolean
  readonly disabled: boolean
  readonly selection: RichTextInputSelection
}

export interface RichTextInputMessages {
  toolbar?: string
  selectionBar?: string
  selectionBarReady?: string
  bold?: string
  italic?: string
  strike?: string
  code?: string
  link?: string
  textStyle?: string
  paragraph?: string
  heading?: (level: 1 | 2 | 3) => string
  bulletList?: string
  orderedList?: string
  blockquote?: string
  codeBlock?: string
  undo?: string
  redo?: string
  linkForm?: string
  linkAddress?: string
  linkApply?: string
  linkRemove?: string
  linkInvalid?: string
  formatOn?: (format: string) => string
  formatOff?: (format: string) => string
  linkAdded?: string
  linkRemoved?: string
  inserted?: (label: string) => string
  undone?: string
  redone?: string
  count?: (length: number, maxLength: number) => string
  overLimit?: (over: number) => string
  withinLimit?: string
  submitEmpty?: string
  submitOverLimit?: (over: number) => string
  submitPending?: string
  suggestions?: (count: number) => string
  loadingSuggestions?: string
  noSuggestions?: string
}

/** A field that holds a rich-text document: a comment, an issue's description, a note: the inputs it takes, by the React member's prop names. */
export interface RichTextInputProps {
  /**
   * The drawn annotation that is active, such as the thread the app shows.
   */
  activeAnnotation?: string
  /**
   * The annotations drawn. Default: every one the document holds.
   */
  annotations?: string[]
  'aria-describedby'?: string
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * Focus at mount, with the caret at the end. For a surface that has already moved the person
   * here.
   */
  autoFocus?: boolean
  /**
   * Draws the default footer's cancel Button; needs `onCancel`.
   */
  cancelLabel?: string
  /**
   * The editable element.
   */
  controlRef?: ControlRef<HTMLDivElement>
  defaultValue?: RichTextDocument
  disabled?: boolean
  /**
   * The kinds of entity the field suggests, each with its trigger.
   */
  entities?: RichTextEntitySource[]
  /**
   * The app's own footer, in place of the default.
   */
  footer?: NodeTemplate<[RichTextInputEditor]>
  /**
   * What the field allows. Default: all ten.
   */
  formats?: RichTextFormat[]
  id?: string
  invalid?: boolean
  /**
   * A soft limit in code points (`richTextLength`): draws the count, and marks the field invalid
   * past it.
   */
  maxLength?: number
  /**
   * How tall the text grows before it scrolls, in body lines. Default 12.
   */
  maxRows?: 6 | 12 | 'none' | 24
  /**
   * Every label and announcement, in the app's words.
   */
  messages?: RichTextInputMessages
  /**
   * The surface's minimum height, in body lines. Default 3.
   */
  minRows?: 1 | 3 | 6 | 12
  /**
   * Adds a hidden input holding `serializeRichText(value)`.
   */
  name?: string
  /**
   * The app is saving: the submit shows loading, the field is read-only, and a submit is
   * refused.
   */
  pending?: boolean
  placeholder?: string
  readOnly?: boolean
  /**
   * The app's controls for the selected text (comment, react), first in the selection bar.
   */
  selectionActions?: NodeTemplate<[RichTextInputEditor]>
  /**
   * Draws the default footer's submit Button; needs `onSubmit`.
   */
  submitLabel?: string
  /**
   * The app's own controls at the toolbar's end: attach, emoji.
   */
  toolbar?: NodeTemplate<[RichTextInputEditor]>
  /**
   * Where the format controls are: a fixed row over the text, or a bar at the selected text.
   */
  toolbarPlacement?: 'fixed' | 'selection'
  value?: RichTextDocument
}

